## Code Example
```javascript
class BucketCounter {
  constructor(D) {
    this.D = D;
    this.buckets = new Array(D).fill(0);
    this.max = 0;
  }
  updateBatch(batch, hashFn) {
    for (const c of batch) {
      const b = hashFn(c) % this.D;
      this.buckets[b] += 1;
      if (this.buckets[b] > this.max) this.max = this.buckets[b];
    }
  }
  query(t) { return this.max >= t; }
}
```

